import { text, vstack, box, bold, green } from '@tuix/view'

const title = bold(text('Status'))
const body = green(text('All systems OK'))
const panel = box(vstack(title, body))

// panel.render() returns an Effect that yields terminal text

import { Effect } from 'effect'
import { runApp } from '@tuix/runtime'
import { text } from '@tuix/view'

type Model = { count: number }
type Msg = { type: 'inc' }

const component = {
  init: Effect.succeed([{ count: 0 }, []] as const),
  update: (msg: Msg, model: Model) =>
    Effect.succeed(
      msg.type === 'inc'
        ? [{ count: model.count + 1 }, []] as const
        : [model, []] as const
    ),
  view: (model: Model) => text(`Count: ${model.count}`),
}

await Effect.runPromise(runApp(component, { fps: 60 }))

import { $state, $states, $derived, bindMvuPush } from '@tuix/reactive'

// Name string is required for model field mapping under Bun rewrites
const count = $state(0, 'count')
const { label } = $states({ label: 'hi' })
const doubled = $derived(() => count() * 2)

// Runtime binds this; named $set becomes { type: 'set', key, value }
bindMvuPush((msg) => {
  // push UserMsg into the MVU queue
  console.log(msg.type, msg.key, msg.value)
})

count.$set(2)
label.$set('ready')
